  "steps": [
    {
      "id": 1,
      "claim": "Dualism is a theory in public international law that treats international law and domestic (municipal) law as separate legal orders.",
      "evidence": "Standard definitions in international law textbooks (e.g., Shaw, *International Law* 8th ed.; Crawford, *Brownlie's Treaties*).",
      "weight": 0.35,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Under dualism, international law does not have direct effect in the domestic legal system unless it is incorporated by legislation (the transformation doctrine).",
      "evidence": "Doctrine of transformation; case law such as *R v Secretary of State for the Home Department, ex parte Simms* (UK) and similar rulings in dualist states.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The defining feature of dualism is the separation of the two systems, not a claim of equal hierarchy or absolute domestic supremacy.",
      "evidence": "Scholarly analysis (e.g., Malcolm N. Shaw, *International Law*, ch. 5) emphasizes that dualism focuses on distinctness; hierarchy is a matter of domestic implementation, not a doctrinal principle.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Option B (‘Under dualism, international and domestic laws comprise distinct legal systems’) accurately captures the core dualist principle described in steps 1‑3.",
      "evidence": "The wording of option B matches the definition and consequence of dualism given in steps 1‑3.",
      "weight": 0.10,
      "depends_on": [1, 3]
    },
    {
      "id": 5,
      "claim": "Options A, C, and D each contain statements inconsistent with dualism: A describes monism (a unified system); C adds an unwarranted ‘equal in hierarchy’ claim; D overstates by saying domestic law always prevails.",
      "evidence": "Comparative literature on monism vs. dualism shows A is monist; C’s hierarchy is not a doctrinal element; D’s absolute supremacy contradicts the transformation requirement of dualism.",
      "weight": 0.10,
      "depends_on": [1, 2, 3]
    }
  ],
  "answer": "B",
  "confidence": 0.98,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Describes monism, which posits a unified legal system, contrary to the dualist separation."
    },
    {
      "answer": "C",
      "reason_rejected": "Introduces an ‘equal in hierarchy’ claim not part of the dualist doctrine."
    },
    {
      "answer": "D",
      "reason_rejected": "Claims domestic law always prevails, an overstatement of the dualist position."
    }
  ]
}
